let overAllTexture
let num = 1200;
let pos, vel;
let bakedCSVelLength = 5;
let bakedCSVel = [];


function setup() {
	createCanvas(800, 800);
	background(0);
	overAllTexture=createGraphics(width,height)
	overAllTexture.loadPixels()
	for(var i=0;i<width+50;i++){
		for(var o=0;o<height+50;o++){
			overAllTexture.set(i,o,color(255,noise(i/3,o/3,i*o/50)*random([0,40,80])))
		}
	}
	overAllTexture.updatePixels()

	 resetParticles();
	for(let i = 0; i < bakedCSVelLength; i++) {
		bakedCSVel[i] = createVector(cos(i * (TWO_PI/bakedCSVelLength)), sin(i * (TWO_PI/bakedCSVelLength))).mult(0.1);

	overAllTexture.updatePixels()
	fill(255)
	//rect(0,0,width,height)
	drawingContext.shadowColor = color(255,20)
	drawingContext.shadowOffsetY = 3
	drawingContext.shadowOffsetX = 2
	drawingContext.shadowBlur = 15
	}
}

function draw() {
	background(0,0.1);
	frameRate(40)

	for (let i = 0; i < pos.length; i++) {
		pos[i].add(vel[i]);
		vel[i].add(bakedCSVel[floor(random(bakedCSVelLength))]);


